def generate_long_text(outline):
    sections = []
 for section in outline:
        prompt = f"""
        文章整体大纲：{outline}
        已生成的内容摘要：{summarize(sections)}

        请生成以下章节的完整内容：
 {section.title}
 {section.requirements}

        注意与前文的衔接和一致性。
        """
        content = llm.generate(prompt)
        sections.append(content)
 return "\n\n".join(sections)
